\big((A'\times B_0\times e)\cup(A'\times A_0\times I)\arrow[r]\arrow[d,"h(i_0\times\mathrm{id}_{A'},I,e)"] & \big((B'\times B_0\times e)\cup\big((B'\times A_0)\times I\big)\arrow[d,"h(i_0\times\mathrm{id}_{B'},I,e)"']\\
